int sum_to_10(void) {
    int sum = 0;
    for (int i = 1; i <= 10; i++)
        sum += i;
    return sum;
}
/* gcc -O0 keeps sum and i in memory (41 bytes).
   gcc -O2 computes the answer at compile time:
       mov eax, 55
       ret                                       */

// A tiny stack VM: bytecode is a list of [operation, argument] pairs.
const code = [["push", 2], ["push", 3], ["add"], ["push", 4], ["mul"], ["print"]];
const stack = [];
for (const [op, arg] of code) {
  if (op === "push") stack.push(arg);
  else if (op === "add") stack.push(stack.pop() + stack.pop());
  else if (op === "mul") stack.push(stack.pop() * stack.pop());
  else if (op === "print") console.log(stack.pop());
}
// prints 20, which is (2 + 3) * 4

